import {RECIPE_CASES,RECIPE_INGREDIENTS,RECIPE_MODEL,RECIPE_CONVERSATION} from './measuring-recipes-content.mjs';
import {recipeState,recipeView,chooseRecipe,nextRecipe,setRecipePage,chooseRecipeIngredient,fillRecipeJug,returnRecipeJug,pourRecipeJug,returnRecipePortion,resetRecipeApparatus,setRecipeReading,setRecipeUnit,checkRecipeReading,checkRecipeTray,useRecipeSupport,stepRecipeExample,keepRecipe,recoverRecipes} from './measuring-recipes-core.mjs';
import {recipeJugArt,recipeIntervalStrip,recipeIngredientMark} from './measuring-recipes-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const name=id=>RECIPE_INGREDIENTS.find(i=>i.id===id)?.name||'empty jug';
const pages=[['measure','Measure'],['tray','Check the tray'],['keep','Keep or change']];
const btn=(attrs,label,{disabled=false,primary=false,on=null}={})=>`<button type="button" class="${primary?'primary':'secondary'}${on?' selected':''}" ${attrs}${disabled?' disabled':''}${on===null?'':` aria-pressed="${on}"`}>${label}</button>`;
function header(){return '<header class="mr-heading"><a class="back" href="#cafe"><span aria-hidden="true">←</span> Back to my café order</a><h1>The Measuring Kitchen</h1><p>A measured tray for our next community dinner.</p><p><a href="#science/measure">Use the separate Measuring Desk for two adult-reported real-jug readings</a></p></header>';}
function request(c){return `<section class="mr-recipe-card" aria-label="The original recipe request"><div><strong>${esc(c.title)} · one pretend batch</strong><p>${esc(c.purpose)}</p></div><dl>${RECIPE_INGREDIENTS.map(i=>`<div><dt>${recipeIngredientMark(i.id)} ${esc(i.name)}</dt><dd>${c.targets[i.id]} mL</dd></div>`).join('')}</dl></section>`;}
function chooser(r){return `<section class="mr-chooser"><h2 id="mr-title" tabindex="-1">Which dinner tray shall we make?</h2><p>Fill, read and pour. You can pour any portion back and try another way.</p><div class="mr-case-grid">${RECIPE_CASES.map(c=>btn(`data-mr-case="${c.id}"`,`<strong>${esc(c.title)}</strong><span>${esc(c.purpose)}</span><small>${r.cases[c.id]?'Your tray is waiting':'A new tray to make'}${r.cases[c.id]?.kept?' · kept':''}</small>`)).join('')}</div><p class="tiny">Six recipes to visit again and again. Your café guest and jars stay as they are.</p></section>`;}
function feedback(v){return `<div id="mr-reading-feedback" class="mr-feedback" tabindex="-1" role="status"${v.readingFeedback?'':' hidden'}>${esc(v.readingFeedback)}</div><p id="mr-reading-error" class="mr-input-error" role="status"${v.inputError?'':' hidden'}>${esc(v.inputError)}</p>`;}
function reading(v){const r=v.work.reading;return `<section class="mr-reading"><h3>What does the jug show?</h3><p>Read the jug as it is now, even if it differs from the recipe.</p><form id="mr-reading-form" novalidate><div class="mr-reading-fields"><label>My number<input id="mr-reading" name="reading" type="text" inputmode="numeric" autocomplete="off" maxlength="24" value="${esc(r.text)}" aria-describedby="mr-reading-status mr-reading-error"></label><label>My unit<select id="mr-unit" name="unit"><option value=""${r.unit===null?' selected':''}>Choose a unit</option>${[['mL','mL · milliliters'],['g','g · grams'],['items','items']].map(([id,label])=>`<option value="${id}"${r.unit===id?' selected':''}>${label}</option>`).join('')}</select></label></div><p id="mr-reading-status" class="tiny">${v.work.readingStale?'Your earlier number is still here. The jug may have changed, so check again.':v.work.feedback.reading?'You checked this number. You can keep pouring.':'You can check your number, or keep pouring.'}</p><button type="submit" class="secondary">Check my reading and unit</button></form>${feedback(v)}</section>`;}
function station(v){const a=v.actions,j=v.model.jug,id=v.work.selectedIngredient;return `<section class="mr-station" aria-label="Measuring jug and controls"><div class="mr-jug"><strong id="mr-jug-title" tabindex="-1">Measuring jug</strong>${recipeJugArt(j.amount,j.ingredient)}<span class="mr-current-ingredient">${recipeIngredientMark(id)} ${esc(name(j.ingredient||id))}${j.amount===0?' · empty':''}</span></div><div class="mr-hands"><div class="mr-ingredient-buttons" role="group" aria-label="Choose an ingredient">${RECIPE_INGREDIENTS.map(i=>btn(`data-mr-ingredient="${i.id}"`,`${recipeIngredientMark(i.id)} ${esc(i.name)}`,{disabled:j.amount>0&&id!==i.id,on:id===i.id})).join('')}</div>${!a.chooseIngredient.enabled?`<p class="tiny mr-limit">${esc(a.chooseIngredient.reason)}</p>`:''}<div class="mr-fill-controls">${btn('data-mr-fill','Add 50 mL',{disabled:!a.fill.enabled,primary:true})}${btn('data-mr-return-jug="one"','Pour 50 mL back',{disabled:!a.returnJug.enabled})}${btn('data-mr-return-jug="all"','Pour it all back',{disabled:!a.returnJug.enabled})}</div>${!a.fill.enabled?`<p class="tiny mr-limit">${esc(a.fill.reason)}</p>`:''}${btn('data-mr-pour',`Pour into ${esc(name(j.ingredient||id))} jar`,{disabled:!a.pour.enabled,primary:true})}${!a.pour.enabled&&j.amount>0?`<p class="tiny mr-limit">${esc(a.pour.reason)}</p>`:''}<details class="mr-sources"><summary>How much is left to pour</summary>${RECIPE_INGREDIENTS.map(i=>`<p>${esc(i.name)}: ${v.sources[i.id]} mL left.</p>`).join('')}<p class="tiny">Liquid you pour back goes home to its own ingredient. These supplies are only for this tray.</p></details></div></section>`;}
function jars(v,interactive=true){return `<section class="mr-tray" aria-label="Separate preparation jars"><h3>Preparation tray</h3><p class="tiny">Two separate jars. The jars only fill when you pour.</p><div class="mr-jars">${RECIPE_INGREDIENTS.map(i=>{const n=v.model.portions[i.id],a=v.actions?.returnPortions[i.id];return `<section class="mr-prep-jar"><h4>${recipeIngredientMark(i.id)} ${esc(i.name)}</h4>${recipeJugArt(n,i.id,{jar:true,label:`${i.name} preparation jar`})}<p class="mr-jar-amount">${n} mL in this jar</p>${interactive?`<div class="mr-jar-controls">${btn(`data-mr-return-portion="${i.id}"`,'Pour 50 mL back into the jug',{disabled:!a.enabled})}${btn(`data-mr-clear-portion="${i.id}"`,'Empty this jar',{disabled:n===0})}</div>${!a.enabled&&n>0?`<p class="tiny mr-limit">${esc(a.reason)}</p>`:''}`:''}</section>`;}).join('')}</div></section>`;}
function trayFeedback(v){if(!v.work.feedback.tray)return '<div id="mr-tray-feedback" tabindex="-1" role="status" hidden></div>';const a=v.latestTray.assessment;return `<section id="mr-tray-feedback" class="mr-feedback" tabindex="-1" role="status"><h3>Compared with the recipe</h3><ul>${RECIPE_INGREDIENTS.map(i=>{const x=a.ingredients[i.id];return `<li><strong>${esc(i.name)}:</strong> ${x.amount} mL ${x.status==='matches'?'matches':x.status==='below'?'is below':'is above'} the ${x.target} mL request.</li>`;}).join('')}</ul><p>${a.ready?'Both portions match and the jug is empty. Your tray is ready to set out.':a.portionsMatch?'Both portions match. There is still extra liquid in the jug. Pour it back to set out the tray.':'You can change any portion, or keep the tray as it is.'}</p></section>`;}
function kept(w){if(!w.kept)return '<p>No kept tray yet. An unfinished one can be kept too.</p>';const k=w.kept,a=k.assessment;return `<section id="mr-kept" class="mr-kept" tabindex="-1"><h3>Your kept dinner tray</h3><p>${a.ready?'The two portions matched, with an empty jug.':'You kept this tray before it was finished.'}</p><dl>${RECIPE_INGREDIENTS.map(i=>`<div><dt>${recipeIngredientMark(i.id)} ${esc(i.name)}</dt><dd>${k.model.portions[i.id]} mL · request ${k.source.targets[i.id]} mL</dd></div>`).join('')}<div><dt>Separate measuring jug</dt><dd>${k.model.jug.amount} mL${k.model.jug.ingredient?` of ${esc(name(k.model.jug.ingredient))}`:''}</dd></div></dl><details><summary>For grown-ups: reading and help kept with this tray</summary><p>Reading: ${k.reading.text===''?'blank':esc(k.reading.text)}; unit: ${esc(k.reading.unit||'not chosen')}. ${k.readingStale?'This number was read from an earlier jug.':''}</p><p>Visible-source practice${k.familiar?', familiar':''}. Support recorded: ${esc(Object.keys(k.support).join(', '))}.</p></details><p class="tiny">Your kept tray stays the same while you pour. To save a new one, press Keep this tray again.</p></section>`;}
function support(v){const w=v.work,s=w.support,e=v.example,explain=RECIPE_INGREDIENTS.map(i=>{const d=v.differences[i.id];return `<li>${esc(i.name)}: ${d===0?'the preparation amount matches':d>0?`add ${d} mL to the preparation jar`:`return ${-d} mL from the preparation jar`}.</li>`;}).join('');return `<aside class="mr-support"><div class="mr-controls">${btn('data-mr-support="intervalStrip"','Show equal spaces',{on:!!s.intervalStrip})}${btn('data-mr-support="difference"','Help compare amounts',{on:!!s.difference})}${btn('data-mr-support="workedExample"','A different example',{on:!!s.workedExample})}${btn('data-mr-support="together"',s.together?'We’re working together <span aria-hidden="true">✓</span>':'We’re working together',{on:!!s.together})}<span data-mr-audio>${hearButton(`${v.case.purpose} One batch needs ${v.case.targets['cloud-water']} milliliters of cloud-water and ${v.case.targets['star-water']} milliliters of star-water. ${pages.find(([id])=>id===v.page)?.[1]||'Fill, read and pour'}. You can pour any portion back. You can keep a tray before it is finished.`,'Hear this recipe')}</span></div>${s.intervalStrip?`<section class="mr-help"><h3>Count the equal spaces</h3>${recipeIntervalStrip()}<p>Ten equal 50 mL spaces sit between eleven marks. The jug’s capacity stays 500 mL.</p></section>`:''}${s.difference?`<section class="mr-help"><h3>Compare the amounts</h3><ul>${explain}</ul><p class="tiny">You still do the pouring. Liquid in the jug is counted separately.</p></section>`:''}${e?`<section class="mr-example"><div><h3>${esc(e.title)}</h3><p>${esc(e.request)}</p><p>${esc(e.notice)}</p><p>${e.step===0?'The example starts empty.':`${e.step} equal 50 mL fills: ${e.amount} mL.`}${e.complete?' The level matches its 400 mL request.':''}</p><div class="mr-controls">${btn('data-mr-example="-1"','Previous fill',{disabled:e.step===0})}${btn('data-mr-example="1"','Next example fill',{disabled:e.step===8})}</div></div>${recipeJugArt(e.amount,'cloud-water',{label:'Example jug'})}</section>`:''}</aside>`;}
export function measuringRecipesEntry(){return '<aside class="mr-entry"><div><h2>A measured tray for dinner</h2><p>Fill a jug, read its scale and pour a pretend recipe. You can change every portion.</p></div><a class="secondary" href="#cafe/recipes">Visit the Measuring Kitchen</a></aside>';}
export function measuringRecipesPage(state){const r=recipeState(state);if(!r)return '<section class="mr-workspace" data-mr-root><h1 id="mr-title" tabindex="-1">An earlier recipe notebook is kept</h1><p>This format cannot be opened here. Its exact record stays in notes downloads.</p><button type="button" class="secondary" data-mr-recover>Keep the earlier record and continue</button><p><a href="#cafe">Return to the café</a></p></section>';if(r.page==='choose'||!r.currentCase)return `<div class="mr-workspace" data-mr-root>${header()}${chooser(r)}</div>`;const v={...recipeView(state),page:r.page},w=v.work;let task;if(r.page==='measure')task=`<h2 id="mr-title" tabindex="-1">Measure, then pour a portion</h2><p>Choose an ingredient. Add 50 mL at a time. Read the scale. Pour into its jar.</p>${reading(v)}<div class="mr-mini-tray">${RECIPE_INGREDIENTS.map(i=>`<span>${recipeIngredientMark(i.id)} ${esc(i.name)} jar: <strong>${v.model.portions[i.id]} mL</strong></span>`).join('')}</div><p>${btn('data-mr-page="tray"','Look at my preparation tray')}</p>`;else if(r.page==='tray')task=`<h2 id="mr-title" tabindex="-1">Does this tray fit the recipe?</h2>${jars(v)}${btn('data-mr-check-tray','Check my tray',{primary:true})}${trayFeedback(v)}<p>${btn('data-mr-page="measure"','Read or fill the jug')}${btn('data-mr-page="keep"','Keep or change this tray')}</p>`;else task=`<h2 id="mr-title" tabindex="-1">A dinner tray to keep or change</h2><p>Keep your tray just as it is. You can still change the portions afterward.</p>${jars(v,false)}${btn('data-mr-keep',w.kept?'Keep this tray again':'Keep this dinner tray',{primary:true})}<p>${btn('data-mr-page="tray"','Change my portions')}</p>${kept(w)}<p>${esc(RECIPE_CONVERSATION)}</p><a href="#cafe/sharing">Explore shares at the Sharing Counter</a> <a href="#cafe/batches">Make whole batches for a gathering</a>`;return `<div class="mr-workspace mr-page-${r.page}" data-mr-root>${header()}${request(v.case)}<nav class="mr-pages" aria-label="Measuring Kitchen turn">${pages.map(([id,label],i)=>btn(`data-mr-page="${id}"`,`${i+1}. ${label}`,{on:r.page===id})).join('')}</nav><p class="mr-notice">${esc(RECIPE_MODEL.notice)}${w.familiar?' You have made this tray before.':''}</p><div class="mr-layout">${station(v)}<section class="mr-turn">${task}</section></div><p id="mr-action-status" role="status" tabindex="-1">${esc(v.message)}</p>${support(v)}<details class="mr-model-details"><summary>For grown-ups: about this picture kitchen</summary><p>${esc(RECIPE_MODEL.details)}</p><p>These are invented recipe amounts. The preparation jars stay separate; they are not real cooking instructions.</p></details><div class="mr-footer">${btn('data-mr-page="choose"','All recipes')}${btn('data-mr-next','Next recipe')}${btn('data-mr-reset','Empty everything',{disabled:v.model.jug.amount===0&&RECIPE_INGREDIENTS.every(i=>v.model.portions[i.id]===0)})}<a href="#notes">Grown-up notes</a></div></div>`;}

export function bindMeasuringRecipes(state,ctx){if(!document.querySelector('[data-mr-root]'))return;const focus=selector=>{const el=document.querySelector(selector);ctx.focus?.(el&&!el.disabled?selector:document.querySelector('#mr-jug-title')?'#mr-jug-title':'#mr-title');};const refresh=(target='#mr-title')=>{ctx.save();ctx.render();focus(target);};const status=text=>{const el=document.querySelector('#mr-action-status');if(el){el.textContent=text;ctx.focus?.('#mr-action-status');}};const act=(fn,target='#mr-title',failure='That move will not work right now. Your portions are still here.')=>{const result=fn();if(result!==false&&result!==null)refresh(target);else status(failure);};const all=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>fn(b)));all('[data-mr-case]',b=>act(()=>chooseRecipe(state,b.dataset.mrCase)));all('[data-mr-page]',b=>act(()=>setRecipePage(state,b.dataset.mrPage)));all('[data-mr-next]',()=>act(()=>nextRecipe(state)));all('[data-mr-recover]',()=>act(()=>recoverRecipes(state)));all('[data-mr-ingredient]',b=>{if(recipeView(state)?.work?.selectedIngredient===b.dataset.mrIngredient)return;act(()=>chooseRecipeIngredient(state,b.dataset.mrIngredient),`[data-mr-ingredient="${b.dataset.mrIngredient}"]`,'Pour this ingredient back or into its jar first.');});all('[data-mr-fill]',()=>act(()=>fillRecipeJug(state),'[data-mr-fill]'));all('[data-mr-return-jug]',b=>act(()=>returnRecipeJug(state,b.dataset.mrReturnJug==='all'),`[data-mr-return-jug="${b.dataset.mrReturnJug}"]`));all('[data-mr-pour]',()=>act(()=>pourRecipeJug(state),'[data-mr-pour]'));all('[data-mr-return-portion]',b=>act(()=>returnRecipePortion(state,b.dataset.mrReturnPortion),`[data-mr-return-portion="${b.dataset.mrReturnPortion}"]`));all('[data-mr-clear-portion]',b=>act(()=>returnRecipePortion(state,b.dataset.mrClearPortion,true),`[data-mr-clear-portion="${b.dataset.mrClearPortion}"]`));all('[data-mr-reset]',()=>act(()=>resetRecipeApparatus(state),'#mr-action-status'));all('[data-mr-check-tray]',()=>act(()=>checkRecipeTray(state),'#mr-tray-feedback'));all('[data-mr-keep]',()=>act(()=>keepRecipe(state),'#mr-kept'));all('[data-mr-support]',b=>act(()=>useRecipeSupport(state,b.dataset.mrSupport),'.mr-support'));all('[data-mr-example]',b=>act(()=>stepRecipeExample(state,Number(b.dataset.mrExample)),`[data-mr-example="${b.dataset.mrExample}"]`));document.querySelectorAll('[data-mr-audio] [data-speak]').forEach(b=>b.addEventListener('click',()=>{useRecipeSupport(state,'audio');ctx.save();}));const clearReading=()=>{for(const id of ['mr-reading-feedback','mr-reading-error']){const el=document.getElementById(id);if(el){el.hidden=true;el.textContent='';}}const el=document.getElementById('mr-reading-status');if(el)el.textContent=recipeView(state).work.readingStale?'Your earlier number is still here. The jug may have changed, so check again.':'You can check your number, or keep pouring.';};document.querySelector('#mr-reading')?.addEventListener('input',e=>{if(setRecipeReading(state,e.target.value)){ctx.save();clearReading();}});document.querySelector('#mr-unit')?.addEventListener('change',e=>{if(setRecipeUnit(state,e.target.value||null)){ctx.save();clearReading();}});document.querySelector('#mr-reading-form')?.addEventListener('submit',e=>{e.preventDefault();const result=checkRecipeReading(state);if(result!==false)refresh(result.valid===false?'#mr-reading-error':'#mr-reading-feedback');});}

export function measuringRecipesNotes(state){if(!Object.hasOwn(state,'measuringRecipes'))return '';return `<details class="panel" data-mr-notes><summary>Measuring Kitchen: portions, readings and revisions</summary><p>Invented recipe cards and an exact picture jug. Reading the scale, naming the unit, pouring each portion and emptying the jug are recorded separately, with the recipe always visible. Help and repeat visits are recorded at each check. These notes show what your child tried and what help they used. They describe play in this picture kitchen only, and they are not grades. A kept tray keeps its original recipe and jug.</p><pre>${esc(JSON.stringify(state.measuringRecipes,null,2))}</pre></details>`;}
